import{_ as t,c as o,b as r,o as a}from"./app-DRXmfGxI.js";const s={};function i(d,e){return a(),o("div",null,e[0]||(e[0]=[r('<p>Admin can import products added on his Shopify Store to <a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace for Shopify</a>, after this, the admin needs to assign those products to the sellers.</p><p>Now, to make the products appear in the Product menu, you need to assign the imported products to the sellers. Then only, the orders will be created in the Multi-vendor App.</p><h2 id="let-s-see-how-the-admin-can-do-this" tabindex="-1"><a class="header-anchor" href="#let-s-see-how-the-admin-can-do-this"><span>Let&#39;s see how the Admin can do this:</span></a></h2><p>Go to: Multivendor Marketplace Admin Panel &gt; Products &gt; Import Products &gt; Click on the &#39;Import Products&#39; button:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/04/Import-Product-From-Shopify-Admin.png" alt="Import Product From Shopify Admin"></p><p>On the redirected page, the admin will get two different methods to import the products in bulk:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/04/Import-Product-From-Shopify-Admin-1.png" alt="Import Product From Shopify Admin (1)"></p><p><strong>Method 1:</strong></p><p>Import products by date range; select the FROM &amp; TO dates between which you want the products from your Shopify store to get imported in your Multivendor Marketplace.</p><p>Note: You need to choose the date range accordingly while importing products because only those products will be imported which are available under the date range selected by you.</p><p><strong>Method 2:</strong></p><p>Import products via CSV file; the admin can also download a dummy CSV file for reference.</p><h2 id="assign-imported-products-to-sellers" tabindex="-1"><a class="header-anchor" href="#assign-imported-products-to-sellers"><span>Assign Imported Products to Sellers</span></a></h2><p>The imported products will be listed on the following page-</p><p>Multivendor Marketplace Admin Panel &gt; Products &gt; Import Products:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/04/Import-Product-From-Shopify-Admin-2.png" alt="Import Product From Shopify Admin (2)"></p><p>Now, the admin needs to click on the three dots (<strong>⋅⋅⋅</strong>) under the ACTION menu &amp; then click on the &#39;Assign product to seller&#39; button. This action will give you a pop-up:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/04/Import-Product-From-Shopify-Admin-3.png" alt="Import Product From Shopify Admin (3)"></p><p>On this pop-up, the admin can change the product type (normal/global/digital) &amp; then he needs to enter the seller email ID.</p><p><strong>Mark</strong>:<br> If the product has variants then admin can&#39;t change the product type to Global/Digital while assigning them to the seller.</p><h3 id="demo-details" tabindex="-1"><a class="header-anchor" href="#demo-details"><span>Demo Details</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/pages/demo</a></p>',22)]))}const p=t(s,[["render",i]]),l=JSON.parse(`{"path":"/classic/products/Import-products.html","title":"Import Products","lang":"en-US","frontmatter":{"title":"Import Products","description":"Import Products","date":"2025-07-02T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"Let's see how the Admin can do this:","slug":"let-s-see-how-the-admin-can-do-this","link":"#let-s-see-how-the-admin-can-do-this","children":[]},{"level":2,"title":"Assign Imported Products to Sellers","slug":"assign-imported-products-to-sellers","link":"#assign-imported-products-to-sellers","children":[{"level":3,"title":"Demo Details","slug":"demo-details","link":"#demo-details","children":[]}]}],"git":{"updatedTime":1753339261000,"contributors":[{"name":"Chirag Tyagi","username":"","email":"chiragtyagi.bd878@webkul.in","commits":2}],"changelog":[{"hash":"4d7cb63e3deaad0bee668591c934df80c08c1432","time":1753339261000,"email":"chiragtyagi.bd878@webkul.in","author":"Chirag Tyagi","message":"added themes"},{"hash":"3bea77852c5b40875767f79601c1175d54f0de18","time":1751440278000,"email":"chiragtyagi.bd878@webkul.in","author":"Chirag Tyagi","message":"added some product configurations"}]},"filePathRelative":"classic/products/Import-products.md"}`);export{p as comp,l as data};
